-- Reflection lessons: what Zoro learned from a tool-call outcome.
-- Apply once in the Supabase SQL editor (same project as zoro_episodes).
--
-- One row is written when a tool call fails (and optionally after a
-- notable success). The lesson is generated by a small Anthropic call
-- in zoro_lessons.reflect_on_episode().
--
-- Status semantics:
--   open       - written but not yet surfaced in a daily report
--   reported   - mentioned to the user in the daily self-report
--   attempted  - self-mod was triggered (autonomous or user-approved)
--   fixed      - the self-mod merged AND the same failure didn't recur
--   wontfix    - user dismissed it, or out-of-scope (needs new resource)

create table if not exists zoro_lessons (
  id                   bigserial primary key,
  created_at           timestamptz not null default now(),
  episode_id           bigint references zoro_episodes (id) on delete set null,
  tool                 text        not null,
  task                 text,
  outcome              text        not null,            -- 'error' | 'success'
  failure_summary      text,                            -- one-line: what went wrong
  lesson               text        not null,            -- one-line reasoning: "next time..."
  suggested_improvement text,                           -- concrete: file + change OR "needs new resource: X"
  needs_resource       text,                            -- non-null when the blocker is missing access/tool
  status               text        not null default 'open',
  attempted_at         timestamptz,
  attempted_branch     text,
  attempted_result     text                             -- 'merged' | 'rolled-back' | 'failed'
);

create index if not exists zoro_lessons_status_idx
  on zoro_lessons (status, created_at desc);
create index if not exists zoro_lessons_tool_idx
  on zoro_lessons (tool, created_at desc);
